def pack(documents, context_length):
    bins = []
    for doc in documents:
        for bin_ in bins:
            if sum(len(d) for d in bin_) + len(doc) <= context_length:
                bin_.append(doc)
                break
        else:
            bins.append([doc])
    return bins

